(function(root){'use strict';
class KeyPool {
 constructor(){this.keys=[];this.projects=new Map();this.active=null;this.busy=false;this.counter=0;}
 add(label,project,key){label=label.trim();project=project.trim().toLowerCase();key=key.trim();if(!label||!project||!key)throw Error('키 이름, Google 프로젝트 ID, API 키를 입력해주세요.');if(label.length>60||!/^[a-z0-9][a-z0-9-]{2,62}$/.test(project))throw Error('실제 Google 프로젝트 ID를 입력해주세요. 영문 소문자·숫자·하이픈만 사용할 수 있습니다.');if(this.keys.length>=20)throw Error('최대 20개 키까지 등록할 수 있습니다.');if(this.keys.some(k=>k.key===key))throw Error('이미 등록한 API 키입니다.');const entry={id:++this.counter,label,project,key,status:'ready'};this.keys.push(entry);if(!this.active)this.active=entry.id;return entry.id;}
 remove(id){if(this.busy)throw Error('요청이 끝난 뒤 키를 삭제해주세요.');const entry=this.keys.find(k=>k.id===id);if(entry)entry.key='';this.keys=this.keys.filter(k=>k.id!==id);if(this.active===id)this.active=this.keys[0]?.id||null;}
 select(id){if(this.busy)throw Error('요청이 끝난 뒤 키를 바꿔주세요.');if(!this.keys.some(k=>k.id===id))throw Error('등록된 키를 선택해주세요.');this.active=id;}
 reset(project,now=Date.now()){const state=this.projects.get(project);if(state&&now<state.retryAt)throw Error('대기 시간이 지나지 않았습니다. 잠시 후 다시 시도해주세요.');this.projects.delete(project);for(const key of this.keys)if(key.project===project)key.status='ready';}
 summary(){return this.keys.map(k=>({id:k.id,label:k.label,project:k.project,active:k.id===this.active,status:this.projects.has(k.project)?'quota':k.status,mask:'••••'+k.key.slice(-4)}));}
 async execute(request,{fallback=true,onSwitch=()=>{}}={}){if(this.busy)throw Error('이미 Gemini 요청을 처리하고 있습니다.');if(!this.keys.length)throw Error('Gemini API 키를 먼저 등록해주세요.');this.busy=true;const candidates=[...this.keys].sort((a,b)=>(b.id===this.active)-(a.id===this.active));const attempted=new Set();let lastError;try{for(const key of candidates){if(!fallback&&key.id!==this.active)continue;if(key.status==='invalid'||this.projects.has(key.project)||attempted.has(key.project))continue;attempted.add(key.project);onSwitch({label:key.label,project:key.project});try{const value=await request(key.key);this.active=key.id;return value;}catch(error){lastError=error;if(error.status===429){this.projects.set(key.project,{retryAt:Date.now()+Math.max(60000,error.retryAfterMs||0)});if(!fallback)throw error;continue;}if(error.status===401||error.status===403){key.status='invalid';throw error;}throw error;}}throw lastError||Error('사용 가능한 프로젝트가 없습니다. Google AI Studio에서 한도를 확인한 후 중지를 해제해주세요.');}finally{this.busy=false;}}
}
if(typeof module!=='undefined'&&module.exports)module.exports=KeyPool;else root.DSKeyPool=KeyPool;
})(typeof window==='undefined'?globalThis:window);
